# (subject, question, answer, star) ; star=1 -> concept the user got wrong (practice sets 1-3, Mock 10 etc.)
Q=[]
def add(s,q,a,star=0): Q.append((s,q,a,star))
S='Ethics'
add(S,"A CFO tells a few analysts a nonpublic earnings warning: may you trade on it?","No. Selective disclosure does not make it public; it is MNPI under II(A). Encourage disclosure and do not act.")
add(S,"Which Standard requires fair and equitable dissemination of a recommendation to all clients?","III(B) Fair Dealing.")
add(S,"Under VII(B), what may and may not be said about the CFA designation?","May say 'I am a CFA charterholder'; may not imply superior skill or promise better returns.")
add(S,"A covered company offers to pay your commercial flights to its conference: allowed?","No (I(B)). Pay your own or your firm's travel. Only a token gift (a branded mug) is fine.",1)
add(S,"When is company-provided travel acceptable under I(B)?","Only for a remote, hard-to-reach site with no commercial transport; reasonable travel, not lavish.",1)
add(S,"A report presents an uncertain forecast as certain: which Standard is violated?","V(B) Communication with Clients: failure to separate fact from opinion and to disclose uncertainty.",1)
add(S,"Which procedures does VI(B) Priority of Transactions recommend for personal trades?","Pre-clearance, and duplicate trade confirmations or statements sent to the employer.")
add(S,"If local law and the Standards differ, which applies under I(A)?","The stricter one.")
add(S,"Whose information is protected by III(E) Preservation of Confidentiality?","Former, current and prospective clients.")
add(S,"A supervisor suspects violations by an employee: what is the appropriate response under IV(C)?","Limit the employee's trading and increase monitoring while the facts are investigated.")
add(S,"May a member use third-party research under V(A)?","Yes, but with reasonable efforts to check it is sound (due diligence).")
add(S,"What does the mosaic theory allow?","Combining public information and nonmaterial nonpublic information.")
add(S,"A personal buy order of four times the average volume to attract a merger partner is which violation?","II(B) Market Manipulation.")
add(S,"What control must a firm use while it holds MNPI about an issuer?","Heightened review of trading (restricted or watch list); it need not stop all trading.")
add(S,"Which fee arrangement for issuer-paid research best supports independence?","A disclosed flat fee, with no bonus, regardless of the conclusion.")
add(S,"What does VI(C) require for referral fees?","Disclose to the employer, clients and prospective clients any compensation or benefit paid or received for referrals.")
add(S,"Must a member tell clients about possible sanctions while a PCP investigation is pending?","No. Sanctions are not official until the process ends.")
add(S,"Before recommending an asset allocation, what must be gathered to meet III(C) Suitability?","The client's profile: objectives, constraints, demographics and liquidity needs.")
add(S,"A new law takes effect before the firm updates its policies: what is the best fix?","A process to learn about legal changes promptly, before they take effect.")
add(S,"Is a firm ban on staff investing in private placements consistent with the Standards?","Yes. VI(B) recommends strict limits; a full ban goes further but is allowed.")
add(S,"Which additional compensation needs the employer's written consent under IV(B)?","Both monetary and non-monetary compensation (cash and gifts).")

S='FSA'
add(S,"A US company holds a euro receivable and the euro appreciates: gain or loss?","Gain (a payable would give a loss).")
add(S,"What mainly determines a subsidiary's functional currency?","Currency of revenues and operating costs (financing is secondary).")
add(S,"Temporal method: where does the remeasurement gain or loss go?","Net income.")
add(S,"Current rate method: where does the translation adjustment go?","OCI, accumulated as CTA in equity.")
add(S,"Net asset exposure and the foreign currency depreciates: what happens to CTA?","It decreases (it increases if the currency appreciates).")
add(S,"Net monetary liability exposure under the temporal method and the foreign currency appreciates: gain or loss?","Loss in net income.")
add(S,"Which translation method gives the higher gross margin when the foreign currency depreciates?","Current rate (temporal gives the higher margin when it appreciates).")
add(S,"In rising prices, which inventory method gives the higher gross margin?","FIFO (older, cheaper costs).")
add(S,"How can a parent reduce balance sheet exposure of a subsidiary with positive net assets?","Reduce net assets, e.g. a dividend paid from local cash.")
add(S,"Proportionate consolidation vs equity method: what is the same, what is higher?","Net income and equity are the same; revenue, assets and liabilities are higher.")
add(S,"Rank total assets under acquisition, proportionate consolidation and equity method.","Acquisition > proportionate > equity method.")
add(S,"What income does an FVPL equity investment generate?","Holding gain or loss plus dividends received (not the investee's net income).")
add(S,"Equity method investment account roll-forward?","Cost + share of net income − share of dividends − amortization of the excess purchase price.")
add(S,"What happens to unrealized profit on an intercompany sale under the equity method?","The investor's share is deferred until the goods are sold to third parties.")
add(S,"Full vs partial goodwill: which gives the higher ROE and ROA?","Partial goodwill (smaller assets and equity, same net income).")
add(S,"Full goodwill formula?","Purchase price ÷ % acquired − fair value of identifiable net assets.")
add(S,"US GAAP interest cost vs IFRS net interest on a pension plan?","US GAAP: beginning PBO × discount rate. IFRS: beginning funded status × discount rate.")
add(S,"Which pension items sit in P&L under IFRS?","Service cost (current and past) and net interest; remeasurements go to OCI.")
add(S,"Which assumption change lowers US GAAP pension cost?","Lower estimated salary increases (a lower expected return on assets raises cost).")
add(S,"A windfall tax benefit on stock compensation: effect on ETR under US GAAP vs IFRS?","US GAAP: lower effective tax rate. IFRS: excess goes to equity, no effect on ETR.")
add(S,"Higher expected volatility at grant: effect on option expense, RSU expense and net income?","Option fair value and expense rise, net income falls; RSUs are unaffected.")
add(S,"Higher expected dividend yield: effect on option expense and net income?","Option value and expense fall; net income rises.")
add(S,"How are RSUs treated in the treasury stock method?","No exercise proceeds; dilutive shares = number − unrecognized expense ÷ average price.")
add(S,"Loss ratio and expense ratio for a P&C insurer?","Loss ratio = (claims paid + change in loss reserves) ÷ net premiums earned; expense ratio = underwriting expenses ÷ net premiums written.")
add(S,"What does a combined ratio below 100% mean?","An underwriting profit (loss ratio + expense ratio < 100%).")
add(S,"After years of weak pricing and capital loss, which phase of the P&C cycle follows?","A hard market: less competition, higher premiums.")
add(S,"Allowance for loan losses ÷ net charge-offs rising signals what?","A larger cushion, more conservative provisioning (provision ÷ charge-offs > 1 is conservative).")
add(S,"What is in Common Equity Tier 1?","Common stock, APIC, retained earnings, OCI, less intangibles and DTAs (preferred stock is Additional Tier 1).")
add(S,"Effect of an inverted yield curve on a bank's net interest revenue?","Falls (short-term funding costs rise relative to long-term lending rates).")
add(S,"A Beneish M-score above −1.78 signals what?","A higher probability of earnings manipulation.")
add(S,"What are discretionary accruals?","The residual of the accruals regression (non-discretionary accruals are explained by business activity).")
add(S,"Receivables growing faster than revenue and net income above CFO: what does it suggest?","Aggressive revenue recognition (low earnings quality).")
add(S,"Segment capex share ÷ segment asset share above 1: what does it suggest?","The segment is being grown (invested in more than its asset share).")
add(S,"Reclassifying interest paid from CFF to CFO: effect on CFO and CFF?","CFO lower, CFF higher.")
add(S,"Five-step DuPont formula for ROE?","Tax burden × interest burden × EBIT margin × asset turnover × financial leverage.")
add(S,"How do you find financial leverage from revenue, asset turnover and liabilities?","Assets = revenue ÷ turnover; equity = assets − liabilities; leverage = assets ÷ equity.",1)
add(S,"In a table with columns 'Most recent year, Previous year, Two years ago', how do you read a trend?","Time runs right to left: the first column is the newest year. Check the column order before reading a trend.",1)
add(S,"Depreciable lives longer than peers: what happens to D/E after adjusting to the shorter peer lives?","Depreciation up, net income and equity down, so D/E rises.")
add(S,"CFO before interest and taxes ÷ operating income well above 1 indicates what?","Earnings are backed by cash flow.")
add(S,"Carrying basis under IFRS 9 for amortized cost, FVOCI and FVPL?","Amortized cost: historical cost. FVOCI and FVPL: fair value.")
add(S,"An SPE funded by an outside bank is consolidated: effect on consolidated cash and debt?","Both increase.")

S='Equity'
add(S,"FCFE formula with a target debt ratio?","NI − (1 − DR)(FCInv − Dep) − (1 − DR)(WCInv).",1)
add(S,"What is excluded from working capital investment for FCFE?","Cash and cash equivalents: WCInv = Δ(current assets excl. cash) − Δ(current liabilities).",1)
add(S,"When is FCFE preferred over a dividend discount model?","Dividends differ from capacity to pay, no dividends, or a control perspective.")
add(S,"Residual income formula?","RI = net income − cost of equity × beginning book value of equity.")
add(S,"Residual income model value?","V0 = B0 + present value of expected residual income.")
add(S,"Market value added (MVA)?","Market value of capital − book value of total capital (equity-only: V0 − B0).")
add(S,"EVA formula?","NOPAT − WACC × invested capital.")
add(S,"Compare NOPAT with what, and net income with what?","NOPAT (before interest) with WACC; net income (after interest) with the cost of equity.")
add(S,"Single-stage RI model value?","V0 = B0 + B0(ROE − r)/(r − g).")
add(S,"Justified P/B in the RI framework?","P/B = 1 + (ROE − r)/(r − g) = (ROE − g)/(r − g).")
add(S,"If ROE equals the cost of equity, what is the intrinsic value?","Book value (no residual income).")
add(S,"What does a persistence factor of 1 mean, and near 0?","1: residual income stays constant forever. Near 0: it vanishes right after the horizon.")
add(S,"Which companies tend to have a low persistence factor?","Extreme ROE, high accruals, special (non-recurring) items.")
add(S,"Terminal value in a multistage RI model with persistence factor ω?","RI(T+1) ÷ (1 + r − ω), discounted back from T.")
add(S,"If the terminal price is given (or price = book at the horizon), what is the terminal term?","PV of (P_T − B_T); it is zero when price equals book. No persistence factor is needed.")
add(S,"Clean surplus relation?","B1 = B0 + EPS − DPS (no other changes in equity).")
add(S,"Which items violate clean surplus?","OCI items such as unrealized AFS gains and currency translation adjustments.")
add(S,"Does the RI model recognize value earlier or later than a DDM?","Earlier (a large part comes from current book value).")
add(S,"Non-recurring items in RI valuation: adjust income or book value?","Adjust income, not book value.")
add(S,"Value of a perpetual preferred share?","D ÷ r.")
add(S,"DLOC from a control premium?","DLOC = 1 − 1/(1 + control premium). Convert a premium to a discount first.",1)
add(S,"Total discount from DLOC and DLOM?","1 − (1 − DLOC)(1 − DLOM): they multiply, not add.",1)
add(S,"Mean or median P/E for comparables with an outlier?","Median.")
add(S,"Capitalized cash flow method (CCM) formula?","Value = FCFF1 ÷ (WACC − g), or FCFE1 ÷ (r − g); use next year's cash flow.")
add(S,"Excess earnings method (EEM): what are the components?","Working capital + fixed assets (tangible) + capitalized excess earnings (intangibles).")
add(S,"Excess earnings in EEM?","Normalized earnings − required return on working capital and fixed assets.")
add(S,"The three approaches to private company valuation?","Income (DCF, CCM, EEM), market (GPCM, GTM, PTM), asset-based.")
add(S,"Synergistic or financial control premium when the target is combined with another portfolio company?","Synergistic (higher than a financial premium).",1)
add(S,"What does normalizing earnings mean?","Adjusting revenues and costs (non-market owner pay, personal expenses, non-recurring items) so the company can be compared with public peers.")
add(S,"An owner is paid less than the market rate: normalized EBITDA goes up or down?","Down, by the gap (costs are understated).")
add(S,"Trailing P/E denominator vs forward vs normalized?","Trailing: last four quarters' EPS. Forward: expected EPS. Normalized: average over a business cycle.")
add(S,"Sustainable growth rate?","g = retention ratio × ROE.")

S='Fixed Income'
add(S,"When can OAS of two bonds be compared, and which is cheaper?","Same credit rating and same tree; the larger OAS is cheaper.")
add(S,"Are the rates in a binomial tree forecasts?","No. They are stochastic paths calibrated to today's curve and the volatility assumption.")
add(S,"Inputs to calibrate an interest rate tree?","Volatility, an interest rate model, and market values of benchmark bonds.")
add(S,"Does volatility change the tree value of an option-free bond?","No: same as the spot rate value.")
add(S,"Callable and putable bond values in terms of a straight bond?","Callable = straight − call; putable = straight + put.")
add(S,"Volatility rises: effect on callable, putable, and their OAS?","Callable value falls, putable rises; OAS of the callable falls, OAS of the putable rises.")
add(S,"Rates fall sharply: what happens to a callable bond's duration and convexity?","Duration falls and convexity turns negative.")
add(S,"What is the effective duration of a floating-rate note?","About the time to the next reset.")
add(S,"Upward-sloping curve flattens (level unchanged): effect on the call option value?","Call value rises (forward rates fall).")
add(S,"Conversion price vs market conversion price?","Conversion price = par ÷ conversion ratio; market conversion price = market price ÷ conversion ratio.")
add(S,"Minimum value of a convertible bond?","The greater of conversion value and straight value.")
add(S,"Conversion price above the share price: what does the convertible behave like?","A bond (driven by rates and credit spread).")
add(S,"Dividend above the threshold: effect on the conversion ratio?","It increases (conversion price falls).")
add(S,"Value of a callable, putable convertible?","Straight + call on stock − call on bond + put on bond.")
add(S,"Pathwise valuation?","Discount each cash flow by the product of the one-period rates along the path.")
add(S,"Forward rate f(2,1) from spot rates?","(1 + s3)³ ÷ (1 + s2)² − 1.")
add(S,"Forward price of a zero F(j,k)?","1 ÷ (1 + f(j,k))^k; the exponent is the length of the forward period.")
add(S,"Rolling down the curve: how is the return computed?","Buy price from today's spot, sell price from the shorter-maturity spot (curve unchanged); annualize over the holding period.")
add(S,"Projected spot curve below the forward curve: bond valued how?","Undervalued: buy.")
add(S,"What does the dominance principle say?","Buy the asset with the lower price per unit of payoff and sell the other.")
add(S,"Bullish steepening, bullish flattening, bearish flattening?","Bullish = yields fall. Steepening: short yields fall more (recession). Flattening: long yields fall more (flight to quality, extend duration with a barbell). Bearish flattening: short yields rise more (expansion).")
add(S,"Swap spread, I-spread, Z-spread, TED spread?","Swap spread = swap rate − government yield; I-spread = bond yield − swap rate; Z-spread: constant spread on spot rates to match price; TED = 3-month MRR − T-bill yield.")
add(S,"When is the swap curve a better benchmark than the government curve?","When government bonds are illiquid.")
add(S,"Which YTM assumptions apply, and what if coupons are reinvested below the YTM?","Held to maturity, no default, reinvestment at the YTM; a lower reinvestment rate gives a realized return below the YTM.")
add(S,"Expected loss and loss given default?","Expected loss = PD × LGD; LGD = 1 − recovery rate.",1)
add(S,"Effect of credit migration on expected return?","Negative: downgrades widen spreads more than upgrades narrow them.")
add(S,"Fair value of a risky bond and its credit spread?","Fair value = VND − CVA; spread = YTM(fair value) − benchmark YTM.")
add(S,"Constant hazard rate h: PD and survival probability?","PD_t = PS(t−1) × h; PS_t = (1 − h)^t. Varying hazard rates: PS_t = Π(1 − h_i).")
add(S,"Lower risk-neutral PD: effect on CVA and credit spread?","CVA falls, fair value rises, spread falls.")
add(S,"Structural model: how are equity and risky debt viewed?","Equity = call on the assets; risky debt = riskless debt − put on the assets.")
add(S,"Weakness of a reduced-form model?","It does not explain why default happens (default is a surprise); its strength is that assets need not trade.")
add(S,"A CDS coupon of 1% and a spread of 1.8%: who pays upfront?","The protection buyer. Upfront ≈ (spread − coupon) × CDS duration; price = 100 − upfront.")
add(S,"Protection seller: when does it gain?","When the spread narrows below the original spread (loss if it widens).")
add(S,"Bond spread above CDS spread: what is the basis trade?","Buy the bond and buy protection.")
add(S,"Expecting the CDS curve to steepen: which trade?","Sell protection at the short end, buy protection at the long end.")
add(S,"Economy improves: which index CDS trade?","Sell high-yield protection, buy investment-grade protection.")
add(S,"Expected leveraged buyout financed with debt: stock and CDS trade?","Buy the shares and buy CDS protection.")
add(S,"Which pool analysis fits short-term, homogeneous, granular pools? Medium-term? Non-granular?","Statistical; portfolio; loan-by-loan.")
add(S,"Rating of subordinated debt vs the issuer's senior unsecured rating?","Notched below.")
add(S,"Credit term structure for the highest-rated vs lower-rated issuers?","Highest-rated: flat or slightly upward. Lower-rated: steeper; spreads narrow when growth expectations are strong.")
add(S,"Pure expectations, local expectations, liquidity preference, segmented markets, preferred habitat?","No premium; same short-holding return; premium rising with maturity; never leave a segment; leave if paid enough.")
add(S,"Which short-rate models can go negative?","Vasicek and Ho-Lee can; CIR (σ√r) and KWF (models ln r) cannot. Ho-Lee and KWF are arbitrage-free.")
add(S,"What drives short-term vs long-term rate volatility?","Short-term: monetary policy. Long-term: economy and inflation expectations.")
add(S,"Which key rate duration is highest for an option-free bond?","The one at maturity.")

S='Derivatives'
add(S,"Value of a long forward on a non-dividend stock after initiation?","S_t − F0 ÷ (1 + r)^(T−t).",1)
add(S,"Forward price with a dividend?","S0(1 + r)^T − FV of the dividends (compounded to expiration).")
add(S,"A forward is overpriced versus the model: which arbitrage?","Sell the forward, borrow, buy the asset (cash-and-carry).")
add(S,"A futures price is below the model price: which arbitrage?","Buy the futures, short the bond, lend (reverse cash-and-carry).")
add(S,"Treasury futures equilibrium price?","[(S + AI0)(1 + r)^T − AI_T − FV(coupons)] ÷ conversion factor.")
add(S,"Accrued interest on a bond?","Days since the last coupon ÷ days in the coupon period × the coupon.")
add(S,"Fixed rate of a swap or equity swap from discount factors?","(1 − Z_n) ÷ ΣZ (times periods per year to annualize).")
add(S,"Value of a pay-fixed swap after initiation?","ΣZ × (new fixed rate − old fixed rate) × notional.")
add(S,"Currency swap valuation steps?","Notionals at the initial spot; PV each leg in its own currency's factors; convert at today's spot.")
add(S,"How do you turn fixed-rate debt into floating-rate debt?","Receive fixed and pay floating.")
add(S,"Which instrument gains if rates rise but limits the loss if they do not?","A payer swaption.")
add(S,"Signs of delta, gamma, vega, theta, rho for a long call? For a long put?","Call: +, +, +, −, +. Put: −, +, +, −, −. A short option reverses the signs.")
add(S,"What does a short option position have: gamma and theta signs?","Negative gamma, positive theta.")
add(S,"Option value one day later with daily theta −0.021?","Value today + theta (value falls by 0.021); not gamma.")
add(S,"Delta hedge of a short call position on 1,200 shares?","Buy delta × 1,200 shares.")
add(S,"Is early exercise ever optimal for an American call on a non-dividend stock?","No; it equals the European call.")
add(S,"How do you value an American put on a binomial tree?","Start at maturity and work back; at every node take the larger of the continuation value and the exercise value (K − S).",1)
add(S,"Risk-neutral probability of an up move?","q = (1 + r − d) ÷ (u − d).")
add(S,"What is implied volatility?","The volatility backed out of market option prices; forward-looking.")
add(S,"Volatility smile, skew, surface?","Smile: higher for ITM and OTM than ATM. Skew: varies with strike in one direction. Surface: across strikes and maturities.")
add(S,"Futures price of a commodity with storage costs and convenience yield?","Spot + storage costs − convenience yield; backwardation when convenience yield > storage cost.")
add(S,"A client owning shares buys puts: change in delta, gamma, vega?","Delta lower, gamma positive, vega positive.")

S='Quant'
add(S,"Adjusted R² formula and its special property?","1 − [(n − 1)/(n − k − 1)](1 − R²); it can fall when a variable is added and can be negative.",1)
add(S,"Standard error of estimate?","√[SSE ÷ (n − k − 1)].")
add(S,"Overall F-statistic and nested F-statistic?","(RSS/k) ÷ (SSE/(n − k − 1)); [(SSE_R − SSE_U)/q] ÷ [SSE_U/(n − k − 1)].")
add(S,"AIC vs BIC: purpose and which value is preferred?","AIC for forecasting, BIC for goodness of fit; the lower value (more negative) is better for both.",1)
add(S,"Significant Breusch–Pagan test: problem, effect and fix?","Conditional heteroskedasticity: standard errors too low, t too high; use White robust errors.")
add(S,"Durbin–Watson below the lower critical value: what does it show and what is the fix?","Positive serial correlation; use Newey–West errors.")
add(S,"Signals of multicollinearity and how to detect it?","High R², significant F, insignificant t-statistics; check VIF; drop or combine variables.")
add(S,"Durbin–Watson zones?","0 to dl: positive serial correlation; dl to du: inconclusive; du to 4 − du: none; then inconclusive; 4 − dl to 4: negative.")
add(S,"Mean-reverting level of an AR(1) model?","b0 ÷ (1 − b1); the series moves toward it.")
add(S,"How do you test for seasonality in quarterly and monthly data?","Check the autocorrelation of residuals at lag 4 (quarterly) or lag 12 (monthly); add that lag if significant.")
add(S,"Covariance stationarity requires what?","Constant and finite mean, variance and covariance with own lags.")
add(S,"Dickey–Fuller null hypothesis and what to do if not rejected?","Unit root; first-difference the series.")
add(S,"Regressing one unit-root series on another: when valid?","Valid only if the series are cointegrated (or neither has a unit root).")
add(S,"A random walk as an AR(1): coefficients and best forecast?","b0 ≈ 0, b1 ≈ 1; best forecast is the current value; no mean reversion.",1)
add(S,"ARCH(1) test: which coefficient matters?","Regress squared residuals on lagged squared residuals; c1 significantly different from 0 means ARCH.")
add(S,"Log-linear trend forecast?","ln(y) = b0 + b1·t, so y = e^(b0 + b1·t).")
add(S,"LASSO, SVM, CART, k-means, PCA: one line each?","LASSO: penalized regression, feature selection; SVM: widest-margin linear classifier; CART: non-linear classification and regression; k-means: k chosen in advance; PCA: reduces features.")
add(S,"Agglomerative vs divisive clustering?","Agglomerative: bottom-up (merge). Divisive: top-down (split).")
add(S,"What is a deep learning network?","A neural network with at least two hidden layers.")
add(S,"Overfitting: which learning and the learning curve axes?","Supervised learning; accuracy in validation/test sample vs size of the training sample.")
add(S,"Text cleansing vs text wrangling?","Cleansing: remove HTML, punctuation, numbers, white space. Wrangling: lowercase, stop words, stemming, lemmatization.")
add(S,"Stemming vs lemmatization?","Stemming cuts words to a base (may not be a word); lemmatization uses a dictionary (better, costlier).")
add(S,"Steps of a structured data project in order?","Conceptualization, data collection, preparation and wrangling, exploration, model training.")
add(S,"Winsorization vs trimming; normalization vs standardization?","Winsorize replaces outliers with a percentile value; trimming removes them. Normalization rescales to 0–1 (outlier sensitive); standardization centers at 0 with st. dev. 1.")
add(S,"Order of the harmonic, geometric and arithmetic means?","Harmonic < geometric < arithmetic (equal only if all values are equal).")

S='Portfolio Management'
add(S,"Information ratio formula and its components?","IR = active return ÷ active risk = TC × IC × √BR.")
add(S,"IR of an index fund that meets its objective exactly?","Zero.")
add(S,"Does changing the benchmark change the Sharpe ratio or the information ratio?","Only the information ratio.")
add(S,"Does scaling all active weights change the IR?","No.")
add(S,"What does a closet index fund look like?","Low active risk, Sharpe ratio close to the benchmark.")
add(S,"Active return vs alpha?","Active return = portfolio − benchmark return; alpha is the return beyond what risk exposures explain.")
add(S,"Security selection and asset allocation formulas?","Selection = Σ w_p(R_p − R_b); allocation = Σ R_b(w_p − w_b).")
add(S,"IC when forecasts are correct a share p of the time?","IC = 2p − 1.")
add(S,"Breadth with correlated decisions?","BR = N ÷ [1 + (N − 1)r].")
add(S,"Expected active return from IC, breadth and active risk?","E(R_A) = IC × √BR × σ_A.")
add(S,"Optimal active risk and maximum Sharpe ratio with a transfer coefficient?","σ_A* = TC × (IR ÷ SR_B) × σ_B; SR_P = √(SR_B² + TC²·IR²).")
add(S,"Weight in the active portfolio?","Optimal active risk ÷ active risk of the active portfolio.")
add(S,"Does adding cash to an active portfolio change the Sharpe ratio or the IR?","IR changes; the Sharpe ratio does not.")
add(S,"Macroeconomic, fundamental and statistical factor models?","Macro: factors are surprises, intercept = expected return; fundamental: attributes, sensitivities first; statistical: PCA, hard to interpret.")
add(S,"What does APT assume and not specify?","Returns follow a factor model, specific risk is diversifiable, no arbitrage; it does not specify the number or identity of the factors.")
add(S,"Active return from factor tilts?","Σ (fund − benchmark sensitivity) × factor return; selection = active return − tilts.")
add(S,"What does a style read from active sensitivities mean: size +, value −?","Small-cap and growth.",1)
add(S,"Contribution of a factor to active risk squared?","Factor's active risk (%²) ÷ total active risk squared; active specific risk is the rest.")
add(S,"Parametric VaR: formula and limits?","(z × σ − μ) × value, scaled by √time; ignores liquidity; high kurtosis means normal VaR understates tail risk.")
add(S,"Number of distinct covariances for n factors?","n(n − 1)/2.")
add(S,"ETF trading above NAV: what do authorized participants do?","Create ETF shares by delivering the basket and sell the ETF shares.")
add(S,"ETF uses: liquidity management, rebalancing, completion?","Equitize cash quickly; move to target weights cheaply; fill temporary gaps in the allocation.")
add(S,"Fundamental asset pricing equation?","Price = E(CF) ÷ (1 + Rf + π + θ + φ).")
add(S,"Real rates depend on what?","Higher with higher expected real growth and with higher volatility of real growth; compare real growth (nominal − inflation) first.",1)
add(S,"Positive output gap means what?","Actual GDP above potential: inflation pressure, low unemployment.")
add(S,"Rents: which part is in the discount rate and which in the cash flow?","Tenant credit risk is in the discount rate (φ); rent growth is in the cash flows.",1)

S='Economics'
add(S,"Dornbusch model: how does the currency respond to monetary expansion?","It overshoots (depreciates more than the long run) because prices are sticky.")
add(S,"Portfolio balance approach: effect of sustained deficits financed by debt?","Currency depreciates in the long run.")
add(S,"Mundell–Fleming: expansionary monetary and restrictive fiscal policy with high capital mobility?","Currency depreciates.")
add(S,"Mundell–Fleming: restrictive monetary and fiscal policy with low capital mobility?","Currency appreciates.")
add(S,"Which indicators signal a currency crisis?","CRRIB + M2: capital inflows surge, reserves fall, real exchange rate overvalued, inflation up, banking stress, M2/reserves up.")
add(S,"What is a carry trade and when does it lose?","Borrow the low-yield currency, invest in the high-yield one; it loses if the funding currency appreciates (UIRP failing).")
add(S,"Under uncovered interest parity, what is the high-yield currency expected to do?","Depreciate by the rate difference.")
add(S,"All-in forward rate from forward points?","Spot + points ÷ 10,000.")
add(S,"Mark-to-market of a forward position?","Compare with the current forward rate for the remaining term, then discount to today.")
add(S,"The CAD depreciates against the USD: what happens to the USD/CAD quote?","It falls.")
add(S,"Relative PPP: does it hold in the short run or the long run?","Better in the long run; poor in the short run.")
add(S,"Neoclassical growth: steady-state growth per capita?","θ ÷ (1 − α); capital deepening has diminishing returns.")
add(S,"Neoclassical model and capital flows?","Capital flows from rich to poor countries, helping convergence.")
add(S,"Bid cross rate EUR/AUD from EUR/USD and AUD/USD quotes?","Bid EUR/USD × 1 ÷ offer AUD/USD.")

S='Corporate Issuers'
add(S,"Special dividend vs higher regular dividend?","Special: one-time, no ongoing commitment. Regular increase: permanent commitment (a positive signal).")
add(S,"Stable vs constant payout dividend policy?","Stable: same amount (or smooth growth). Constant payout: same percentage of earnings.")
add(S,"Debt-financed repurchase: when does EPS rise?","When the earnings yield (E/P) exceeds the after-tax cost of debt.")
add(S,"Cash buyback: effect on assets, equity and leverage?","Assets and equity fall; leverage ratios rise.")
add(S,"Price after a stock dividend?","Old price ÷ (1 + stock dividend %).")
add(S,"What is greenmail?","Buying back a hostile bidder's shares at a premium to stop a takeover.")
add(S,"Repurchase methods and prices?","Open market: flexible. Tender or Dutch auction: premium. Negotiated: discount or premium (greenmail).")
add(S,"Reasons for a low payout ratio?","High growth opportunities, high flotation costs, high taxes on dividends.")
add(S,"Which items raise operating income in a merger?","Revenue synergies and cost synergies (dis-synergies and one-time costs lower it).")
add(S,"Which CAPM for a private domestic company and for a subsidiary in an emerging country?","Expanded CAPM (size and company-specific premiums); extended/international CAPM with a country risk premium.")
add(S,"Pre-tax cost of debt for a company with no traded bonds?","Interpolate comparable yields by maturity.")
add(S,"Cross-holdings, pyramids, executives on each other's boards?","Horizontal structure, vertical structure, interlocking directorates.")
add(S,"Controlling votes far above ownership: which problem and which remedy?","Principal–principal conflict; a voting cap.")
add(S,"ESG data: vendors vs company-reported?","Vendors: subjective methods. Company-reported: inconsistent and voluntary.")
add(S,"Why can a green bond have a tighter spread than a conventional bond of the same issuer?","Strong investor demand.")

S='Alternative Investments'
add(S,"REIT vs REOC?","REIT: tax-exempt if it distributes most income, high yield, limited reinvestment. REOC: taxable, more flexibility.")
add(S,"NAVPS method?","Value properties by direct capitalization (NOI ÷ cap rate), add other assets, subtract debt, divide by shares.",1)
add(S,"A highly leveraged REIT trading far below NAVPS: what is the concern?","Refinancing risk (hard to raise capital).")
add(S,"Dedicated short vs short-biased fund?","Dedicated short: almost no long exposure. Short-biased: net short with some long positions.")
add(S,"What makes a life settlement attractive?","Low surrender value, low premiums, earlier death than expected.")
add(S,"Real estate cycle order?","Recovery, expansion, hyper-supply, recession; high vacancy means hyper-supply or recession, and recovery comes next.",1)
add(S,"How do you compare the effect of unreimbursed expenses across properties?","As a percentage of effective gross income, not in dollars.",1)
add(S,"Direct capitalization for a property with temporarily disrupted income?","Use a normalized (stabilized) NOI, or a DCF; not last year's NOI.")
add(S,"Commodity in backwardation: relation of convenience yield and storage costs?","Convenience yield exceeds storage costs.")
